import React from 'react';

const CTASection = () => {
  return (
    <section
      className="relative py-32 bg-cover bg-center bg-fixed"
      style={{
        backgroundImage: `url(https://customer-assets.emergentagent.com/job_rope-products/artifacts/hl0izui8_WhatsApp%20Image%202026-04-14%20at%2012.34.24%20AM%20%281%29.jpeg)`
      }}
    >
      <div className="absolute inset-0 bg-black bg-opacity-60"></div>
      
      <div className="relative container mx-auto px-4 text-center">
        <h2 className="text-white text-4xl md:text-5xl font-light mb-8">
          Providing High-quality Ropes Since 2012
        </h2>
        <a
          href="tel:+919825814883"
          className="inline-block bg-white hover:bg-gray-100 text-[#3d3d3d] font-bold px-12 py-6 text-sm tracking-wider transition-all rounded"
        >
          GET IN TOUCH
        </a>
      </div>
    </section>
  );
};

export default CTASection;
